import React from "react";
import instagramIcon from "../work_assets/navigationIcons/icons8-instagram-64.png";
import emailIcon from "../work_assets/navigationIcons/icons8-mail-64.png";
import linkedinIcon from "../work_assets/navigationIcons/icons8-linkedin-circled-64.png";

const Footer = () => {
  return (
    <div className="py-8 px-4">
      <h3>Socials</h3>
      <div className="flex-">
        <img
          src={instagramIcon}
          width="54"
          height="54"
          alt="logo-placeholder"
        />
        <img src={emailIcon} width="44" height="44" alt="logo-placeholder" />
        <img src={linkedinIcon} width="44" height="44" alt="logo-placeholder" />
      </div>
      <h3>© 2025 Mateo Hernandez. All Rights Reserved.</h3>
    </div>
  );
};

export default Footer;
